// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzzedToken, address from, address to1, uint v) public {
        // fuzzedToken will be a deployed adversarial token that reverts on transferFrom
        // it's not an EOA; we deploy a fresh reverting token bound to the fuzzed address
        // to ensure the external call fails.
        address[] memory tos = new address[](1);
        tos[0] = to1;
        // vm.assume to avoid precompile collisions and the c address
        vm.assume(fuzzedToken != address(c));
        vm.assume(from != address(0) && to1 != address(0));

        // Deploy the adversarial token contract that reverts on transferFrom
        RevertingToken token = new RevertingToken();

        bool ok;
        try c.transfer(from, address(token), tos, v) returns (bool val) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: the call must always revert, because the token reverts.
        assertTrue(!ok);
    }
}

contract RevertingToken {
    // transferFrom always reverts to simulate a failing external call
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("forced revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // Simple call that should succeed; we mock a successful transferFrom by deploying a helper that does not revert.
        Successor successor = new Successor();
        caddress = address(successor);
        bool ret = c.transfer(from, caddress, _tos, v);
        assertTrue(ret);
    }
}

contract Successor {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
